    print(output_a)

    try:
        output_b = extract_and_concatenate_numeric_characters(test_input_without_numbers)
        print(output_b)
    except EmptyDigitSetError as err:
        print(err)

    output_c = extract_and_concatenate_numeric_characters(test_input_only_numbers)
    print(output_c)

