import re

_domain_regex = re.compile(
    r'^(?!-)[A-Za-z0-9-]{1,63}(?<!-)(\.(?!-)[A-Za-z0-9-]{1,63}(?<!-))*\.[A-Za-z]{2,}$'
)

def validate_email(email):
    if not isinstance(email, str) or '@' not in email:
        return False

    local_part, domain_part = email.rsplit('@', 1)

    if not local_part or not domain_part:
        return False

    if not _domain_regex.match(domain_part):
        return False

    allowed_local_chars = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._%+-")
    if not all(char in allowed_local_chars for char in local_part):
        return False

    if local_part.startswith('.') or local_part.endswith('.'):
        return False

    if '..' in local_part:
        return False

    return True

if __name__ == '__main__':
    test_cases = [
        "user@example.com",
        "invalid.email@",
        "@domain.com",
        "user@.com",
        "user@domain.c",
        "valid.email+tag@sub.domain.org",
        "user name@example.com",
        "",
        "a@b.co",
        ".user@example.com",
        "user.@example.com"
    ]
    for case in test_cases:
        print(validate_email(case))

import re

class EmailValidator:
    _LOCAL_PART_PATTERN = r'[a-zA-Z0-9._%+-]+'
    _DOMAIN_PART_PATTERN = r'[a-zA-Z0-9-]+(\.[a-zA-Z0-9-]+)*'
    _TLD_PATTERN = r'\.[a-zA-Z]{2,}'
    _FULL_PATTERN = re.compile(
        rf'^{_LOCAL_PART_PATTERN}@{_DOMAIN_PART_PATTERN}{_TLD_PATTERN}$'
    )

    @staticmethod
    def validate(address):
        if not isinstance(address, str):
            return False
        return bool(EmailValidator._FULL_PATTERN.match(address))

if __name__ == '__main__':
    validator = EmailValidator()
    test_cases = [
        "alex.morgan@tech-corp.io",
        "support_team@server.dev",
        "user@invalid",
        "@nodomain.com",
        "missing.tld@",
        "double@@at.com",
        "simple@domain.org"
    ]

    results = [
        (email, validator.validate(email))
        for email in test_cases
    ]

    for email, is_valid in results:
        print(f"{email}: {is_valid}")
